    fn translate_events(events: Vec<AnthropicEvent>) -> Vec<ModelEvent> {
        let mut t = MessageTranslator::new(false);
        let mut out = Vec::new();
        for e in events {
            for item in t.consume(e).unwrap() {
                out.push(item.unwrap());
            }
        }
        if let Some(last) = t.finish() {
            out.push(last.unwrap());
        }
        out
    }

